input.command:
cd /Users/marcel.a.n.navarro/Dev/zimmermann-pwa
gh api graphql -f query='
{
  repository(owner:"ZimmermannAU", name:"zimmermann-pwa") {
    pullRequest(number:59) {
      reviewThreads(first:100) {
        nodes {
          isResolved
          path
          comments(first:20) { nodes { databaseId author{login} body } }
        }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select((.comments.nodes[].body | test("kebab-case|kebab case";"i"))) | "PATH=\(.path) RESOLVED=\(.isResolved)\n" + ([.comments.nodes[] | "  [\(.databaseId)] \(.author.login): \(.body[0:2500])"] | join("\n---\n")) + "\n============================================\n"'
